function adviseIndexes(queries) {
  const recommendations = [];

  for (const query of queries) {
    const fromMatch = query.match(/FROM\s+(\w+)/i);
    const mainTable = fromMatch ? fromMatch[1] : null;

    let whereCols = [];
    let orderCols = [];
    let groupCols = [];

    const whereMatch = query.match(/WHERE\s+(.+?)(?:ORDER|GROUP|LIMIT|JOIN|$)/i);
    if (whereMatch) {
      const cols = whereMatch[1].match(/(\w+)\s*(?:=|>|<|>=|<=|!=|LIKE|IN)/gi) || [];
      whereCols = cols.map(c => c.replace(/\s*(=|>|<|>=|<=|!=|LIKE|IN).*/i, '').trim())
        .filter(c => !['AND','OR','NOT'].includes(c.toUpperCase()));
    }

    const orderMatch = query.match(/ORDER\s+BY\s+([\w\s,]+?)(?:LIMIT|$)/i);
    if (orderMatch) {
      orderCols = orderMatch[1].split(',').map(p => p.trim().split(/\s+/)[0])
        .filter(c => !['ASC','DESC'].includes(c.toUpperCase()));
    }

    const groupMatch = query.match(/GROUP\s+BY\s+([\w\s,]+?)(?:HAVING|ORDER|LIMIT|$)/i);
    if (groupMatch) {
      groupCols = groupMatch[1].split(',').map(p => p.trim());
    }

    const joinRegex = /JOIN\s+(\w+)\s+\w*\s*ON\s+(\w+\.\w+)\s*=\s*(\w+\.\w+)/gi;
    let jm;
    while ((jm = joinRegex.exec(query)) !== null) {
      const col = jm[3].split('.').pop();
      recommendations.push({ table: jm[1], columns: [col], type: 'single', reason: 'JOIN condition', priority: 'high' });
    }

    if (whereCols.length && orderCols.length && mainTable) {
      recommendations.push({ table: mainTable, columns: [...whereCols, ...orderCols], type: 'composite', reason: 'WHERE + ORDER BY', priority: 'high' });
    } else {
      if (whereCols.length && mainTable) {
        recommendations.push({ table: mainTable, columns: whereCols, type: whereCols.length > 1 ? 'composite' : 'single', reason: 'WHERE clause', priority: 'high' });
      }
      if (orderCols.length && mainTable) {
        recommendations.push({ table: mainTable, columns: orderCols, type: 'single', reason: 'ORDER BY clause', priority: 'medium' });
      }
    }

    if (groupCols.length && mainTable) {
      recommendations.push({ table: mainTable, columns: groupCols, type: 'single', reason: 'GROUP BY clause', priority: 'medium' });
    }
  }

  return recommendations;
}
